// Game UI backed by the local rules engine.
import { createInitialPosition, legalMoves, makeMove, getStatus, getBotMove } from './src/chess.js';

let position = createInitialPosition();
let history = [];
let selectedSquare = null;
let flipped = false;
let thinking = false;
let gameToken = 0;
let lastMove = null;

const files = 'abcdefgh';
const pieceGlyph = { wK: '♔', wQ: '♕', wR: '♖', wB: '♗', wN: '♘', wP: '♙', bK: '♚', bQ: '♛', bR: '♜', bB: '♝', bN: '♞', bP: '♟' };
const rankToRow = rank => 8 - Number(rank);
const squareFromView = (row, col) => `${files[flipped ? 7 - col : col]}${flipped ? row + 1 : 8 - row}`;
const viewFromSquare = square => {
  const col = files.indexOf(square[0]), rank = Number(square[1]);
  return flipped ? [rank - 1, 7 - col] : [8 - rank, col];
};

function renderBoard() {
  const status = getStatus(position);
  const checks = new Set();
  if (status.inCheck) {
    const king = Object.keys(position.board).find(s => position.board[s] === `${position.turn}K`);
    if (king) checks.add(king);
  }
  const legalFromSelected = selectedSquare ? legalMoves(position, selectedSquare) : [];
  const destinations = new Set(legalFromSelected.map(move => move.to));
  const board = $('board');
  board.innerHTML = '';
  for (let row = 0; row < 8; row++) for (let col = 0; col < 8; col++) {
    const square = squareFromView(row, col), piece = position.board[square], button = document.createElement('button');
    button.type = 'button';
    button.className = `square ${((row + col) % 2) ? 'dark' : 'light'}${selectedSquare === square ? ' selected' : ''}${lastMove && (lastMove.from === square || lastMove.to === square) ? ' last' : ''}${checks.has(square) ? ' check' : ''}`;
    button.setAttribute('aria-label', `${square}${piece ? ` ${piece[0] === 'w' ? 'white' : 'black'} ${({K:'king',Q:'queen',R:'rook',B:'bishop',N:'knight',P:'pawn'})[piece[1]]}` : ''}${destinations.has(square) ? ', legal move' : ''}`);
    if (piece) {
      const span = document.createElement('span'); span.className = `piece ${piece[0] === 'w' ? 'white' : 'black'}`; span.textContent = pieceGlyph[piece]; button.append(span);
    }
    if (destinations.has(square)) {
      const dot = document.createElement('span'); dot.className = `move-dot${piece ? ' capture' : ''}`; button.append(dot);
    }
    if (col === 0) { const coord = document.createElement('span'); coord.className = 'coord rank'; coord.textContent = square[1]; button.append(coord); }
    if (row === 7) { const coord = document.createElement('span'); coord.className = 'coord file'; coord.textContent = square[0]; button.append(coord); }
    button.disabled = thinking || status.over;
    button.addEventListener('click', () => onSquareClick(square)); board.append(button);
  }
  $('undo').disabled = thinking || history.length === 0;
  const message = $('game-message'), opponentPill = $('opponent-turn'), yourPill = $('your-turn');
  opponentPill.textContent = thinking ? 'THINKING…' : status.over ? (status.result === 'checkmate' ? 'GAME OVER' : 'GAME DRAWN') : 'READY TO PLAY';
  yourPill.classList.toggle('your-turn', position.turn === 'w' && !thinking && !status.over);
  yourPill.innerHTML = position.turn === 'w' && !thinking && !status.over ? '<span></span> YOUR TURN' : status.over ? 'GAME OVER' : 'BOT TO MOVE';
  if (status.result === 'checkmate') message.textContent = status.winner === 'w' ? 'Checkmate — you win! Wonderful play!' : `${bots[selectedBot].name} wins by checkmate. Rematch?`;
  else if (status.result === 'stalemate') message.textContent = 'A stalemate — a hard-fought draw.';
  else if (status.result === 'draw') message.textContent = 'Draw game — beautifully played.';
  else if (thinking) message.textContent = `${bots[selectedBot].name} is considering a move…`;
  else if (status.inCheck) message.textContent = position.turn === 'w' ? 'Check! Find a way to protect your king.' : `${bots[selectedBot].name} is in check.`;
  else message.textContent = position.turn === 'w' ? 'Your move. Make it a good one!' : `${bots[selectedBot].name} to move.`;
}

function performMove(move) {
  history.push(position);
  position = makeMove(position, move);
  lastMove = move; selectedSquare = null;
  renderBoard();
  if (position.turn === 'b' && !getStatus(position).over) scheduleBotMove();
}

function onSquareClick(square) {
  if (thinking || position.turn !== 'w' || getStatus(position).over) return;
  const piece = position.board[square];
  if (selectedSquare) {
    const candidates = legalMoves(position, selectedSquare).filter(move => move.to === square);
    if (candidates.length) {
      if (candidates.some(move => move.promotion)) return showPromotion(candidates);
      performMove(candidates[0]); return;
    }
    if (piece?.startsWith('w')) { selectedSquare = square; renderBoard(); return; }
    selectedSquare = null; renderBoard(); return;
  }
  if (piece?.startsWith('w')) { selectedSquare = square; renderBoard(); }
}

function showPromotion(moves) {
  const dialog = $('promotion-dialog'), options = $('promotion-options');
  options.innerHTML = '';
  for (const type of ['Q','R','B','N']) {
    const move = moves.find(candidate => candidate.promotion === type);
    if (!move) continue;
    const button = document.createElement('button'); button.type = 'button'; button.setAttribute('aria-label', `Promote to ${({Q:'queen',R:'rook',B:'bishop',N:'knight'})[type]}`); button.textContent = pieceGlyph[`w${type}`];
    button.addEventListener('click', () => { dialog.hidden = true; performMove(move); }); options.append(button);
  }
  dialog.hidden = false; options.querySelector('button')?.focus();
}

function scheduleBotMove() {
  const token = ++gameToken; thinking = true; renderBoard();
  const strength = Math.min(5, Math.max(1, Math.ceil((selectedBot + 1) / 2)));
  window.setTimeout(() => {
    if (token !== gameToken) return;
    const move = getBotMove(position, strength);
    thinking = false;
    if (move) { history.push(position); position = makeMove(position, move); lastMove = move; }
    renderBoard();
  }, 180);
}

function newGame() {
  gameToken++; thinking = false; history = []; selectedSquare = null; lastMove = null;
  position = createInitialPosition(); $('promotion-dialog').hidden = true; renderBoard();
}

$('undo').addEventListener('click', () => {
  if (thinking || !history.length) return;
  gameToken++; thinking = false;
  position = history.pop();
  if (position.turn === 'b' && history.length) position = history.pop();
  selectedSquare = null; lastMove = null; renderBoard();
});
$('flip').addEventListener('click', () => { flipped = !flipped; renderBoard(); });
$('restart').addEventListener('click', newGame);
$('promotion-dialog').addEventListener('click', event => { if (event.target === $('promotion-dialog')) $('promotion-dialog').hidden = true; });
renderBots(); newGame();

