47:   if(from!==home||p.board[home]!==`${c}K`||isInCheck(p,c))return;
48:   const rights=p.castling[c];
49:   if(rights.K&&p.board[square(7,rank)]===`${c}R`&&!p.board[square(5,rank)]&&!p.board[square(6,rank)]&&!isSquareAttacked(p,square(5,rank),enemy)&&!isSquareAttacked(p,square(6,rank),enemy))addMove(moves,home,square(6,rank));
50:   if(rights.Q&&p.board[square(0,rank)]===`${c}R`&&!p.board[square(1,rank)]&&!p.board[square(2,rank)]&&!p.board[square(3,rank)]&&!isSquareAttacked(p,square(3,rank),enemy)&&!isSquareAttacked(p,square(2,rank),enemy))addMove(moves,home,square(2,rank));
51: }
52: function pseudoMoves(p,fromFilter){
53:   const b=p.board,c=p.turn,moves=[],entries=fromFilter?[[fromFilter,b[fromFilter]]]:Object.entries(b);
54:   for(const [from,piece] of entries){if(!piece||colorOf(piece)!==c)continue;const [f,r]=coords(from),t=typeOf(piece);
55:     if(t==='P'){
56:       const step=c==='w'?1:-1,start=c==='w'?1:6,last=c==='w'?7:0,y=r+step;
57:       if(y>=0&&y<8&&!b[square(f,y)]){if(y===last)PROMOTIONS.forEach(x=>addMove(moves,from,square(f,y),x));else addMove(moves,from,square(f,y));const yy=r+2*step;if(r===start&&!b[square(f,yy)])addMove(moves,from,square(f,yy));}
58:       for(const df of [-1,1]){const x=f+df,yy=r+step;if(x<0||x>7||yy<0||yy>7)continue;const to=square(x,yy);if((b[to]&&colorOf(b[to])!==c&&typeOf(b[to])!=='K')||to===p.enPassant){if(yy===last)PROMOTIONS.forEach(z=>addMove(moves,from,to,z));else addMove(moves,from,to);}}
59:     }else if(t==='N'||t==='K'){
60:       for(const [df,dr] of (t==='N'?KNIGHT_STEPS:KING_STEPS)){const x=f+df,y=r+dr;if(x<0||x>7||y<0||y>7)continue;const to=square(x,y);if(!b[to]||(colorOf(b[to])!==c&&typeOf(b[to])!=='K'))addMove(moves,from,to);}
61:       if(t==='K')addCastlingMoves(p,from,moves);
62:     }else{
63:       const dirs=t==='B'?BISHOP_DIRS:t==='R'?ROOK_DIRS:[...BISHOP_DIRS,...ROOK_DIRS];
64:       for(const [df,dr] of dirs){let x=f+df,y=r+dr;while(x>=0&&x<8&&y>=0&&y<8){const to=square(x,y);if(!b[to])addMove(moves,from,to);else{if(colorOf(b[to])!==c&&typeOf(b[to])!=='K')addMove(moves,from,to);break;}x+=df;y+=dr;}}
65:     }
66:   }return moves;
67: }
68: function applyUnchecked(p,m,trackRepetition=true){
69:   const board={...p.board},piece=board[m.from],c=colorOf(piece),t=typeOf(piece),captured=board[m.to];
70:   const [ff,fr]=coords(m.from),[tf,tr]=coords(m.to);delete board[m.from];
71:   if(t==='P'&&m.to===p.enPassant&&ff!==tf&&!captured)delete board[square(tf,tr+(c==='w'?-1:1))];
72:   board[m.to]=t==='P'&&(tr===0||tr===7)?`${c}${PROMOTIONS.includes(m.promotion)?m.promotion:'Q'}`:piece;
73:   if(t==='K'&&Math.abs(tf-ff)===2){const rf=square(tf>ff?7:0,fr),rt=square(tf>ff?5:3,fr);board[rt]=board[rf];delete board[rf];}
74:   const castling={w:{...p.castling.w},b:{...p.castling.b}};if(t==='K')castling[c]={K:false,Q:false};
75:   if(m.from==='a1'||m.to==='a1')castling.w.Q=false;if(m.from==='h1'||m.to==='h1')castling.w.K=false;
76:   if(m.from==='a8'||m.to==='a8')castling.b.Q=false;if(m.from==='h8'||m.to==='h8')castling.b.K=false;
77:   const next={board,turn:opposite(c),castling,enPassant:t==='P'&&Math.abs(tr-fr)===2?square(ff,(fr+tr)/2):null,
78:     halfmoveClock:t==='P'||captured?0:(p.halfmoveClock||0)+1,fullmoveNumber:(p.fullmoveNumber||1)+(c==='b'?1:0),repetitionCounts:trackRepetition?{...(p.repetitionCounts||{})}:(p.repetitionCounts||{})};
79:   if(trackRepetition){const key=repetitionKey(next);next.repetitionCounts[key]=(next.repetitionCounts[key]||0)+1;}return next;
80: }
81: 
82: /** All legal moves, optionally restricted to a source square. */
83: export function legalMoves(p,from){
84:   normalizePosition(p);if(from!==undefined&&!validSquare(from))return [];
85:   return pseudoMoves(p,from).filter(m=>!isInCheck(applyUnchecked(p,m,false),p.turn));
86: }
87: export const getLegalMoves=legalMoves;
88: /** Apply a legal move immutably. Promotion defaults to queen if omitted. */
89: export function makeMove(p,m){
90:   normalizePosition(p);if(!m||!validSquare(m.from)||!validSquare(m.to))throw new TypeError('Move must contain valid from and to squares.');
91:   const legal=legalMoves(p,m.from).find(x=>x.to===m.to&&(m.promotion?x.promotion===m.promotion:!x.promotion||x.promotion==='Q'));
92:   if(!legal)throw new RangeError(`Illegal move: ${m.from}-${m.to}${m.promotion||''}`);return applyUnchecked(p,legal);
93: }
94: 
95: export function toFEN(p){
96:   normalizePosition(p);const rows=[];
97:   for(let r=7;r>=0;r--){let row='',empty=0;for(let f=0;f<8;f++){const piece=p.board[square(f,r)];if(!piece)empty++;else{if(empty)row+=empty;empty=0;row+=colorOf(piece)==='w'?typeOf(piece):typeOf(piece).toLowerCase();}}if(empty)row+=empty;rows.push(row);}
98:   const rights=['w','b'].map(c=>`${p.castling[c].K?(c==='w'?'K':'k'):''}${p.castling[c].Q?(c==='w'?'Q':'q'):''}`).join('')||'-';
99:   return `${rows.join('/')} ${p.turn} ${rights} ${p.enPassant||'-'} ${p.halfmoveClock||0} ${p.fullmoveNumber||1}`;
100: }
101: export function fromFEN(fen){
102:   if(typeof fen!=='string')throw new TypeError('FEN must be a string.');const [placement,turn,rights,ep,half,full]=fen.trim().split(/\s+/),rows=placement?.split('/');
103:   if(!rows||rows.length!==8||!['w','b'].includes(turn))throw new TypeError('Invalid FEN.');const board={};
104:   for(let ri=0;ri<8;ri++){let f=0;for(const ch of rows[ri]){if(/^[1-8]$/.test(ch))f+=Number(ch);else if(/^[prnbqkPRNBQK]$/.test(ch)&&f<8){const c=ch===ch.toUpperCase()?'w':'b';board[square(f++,7-ri)]=`${c}${ch.toUpperCase()}`;}else throw new TypeError('Invalid FEN piece placement.');}if(f!==8)throw new TypeError('Invalid FEN rank width.');}
105:   const p={board,turn,castling:{w:{K:!!rights?.includes('K'),Q:!!rights?.includes('Q')},b:{K:!!rights?.includes('k'),Q:!!rights?.includes('q')}},enPassant:ep&&ep!=='-'?ep:null,halfmoveClock:Number(half)||0,fullmoveNumber:Number(full)||1,repetitionCounts:{}};
106:   if(p.enPassant&&!validSquare(p.enPassant))throw new TypeError('Invalid FEN en-passant square.');p.repetitionCounts[repetitionKey(p)]=1;return p;
107: }
108: export function getStatus(p){
109:   normalizePosition(p);const moves=legalMoves(p),inCheck=isInCheck(p,p.turn);let result='ongoing',reason=null,winner=null;
110:   if(!moves.length){result=inCheck?'checkmate':'stalemate';reason=result;if(inCheck)winner=opposite(p.turn);}
111:   else if((p.repetitionCounts?.[repetitionKey(p)]||0)>=3){result='draw';reason='threefold-repetition';}
112:   else if((p.halfmoveClock||0)>=100){result='draw';reason='fifty-move-rule';}
113:   else if(isInsufficientMaterial(p)){result='draw';reason='insufficient-material';}
114:   return {over:result!=='ongoing',result,reason,winner,inCheck,legalMoves:moves};
115: }
116: export const getGameStatus=getStatus;
117: function isInsufficientMaterial(p){
118:   const pieces=Object.values(p.board).filter(x=>typeOf(x)!=='K');if(!pieces.length)return true;
119:   if(pieces.some(x=>['P','Q','R'].includes(typeOf(x))))return false;if(pieces.length===1)return true;
120:   if(pieces.every(x=>typeOf(x)==='B')){const colors=Object.entries(p.board).filter(([,x])=>typeOf(x)==='B').map(([s])=>{const [f,r]=coords(s);return(f+r)%2;});return colors.every(x=>x===colors[0]);}
121:   return false;
122: }
123: 
124: function evaluateWhite(p){
125:   let score=0;for(const [sq,piece] of Object.entries(p.board)){const c=colorOf(piece),t=typeOf(piece),[f,r]=coords(sq),rr=c==='w'?r:7-r,d=Math.abs(f-3.5)+Math.abs(r-3.5);let pos=0;
126:     if(t==='P')pos=rr*7-Math.abs(f-3.5)*2;else if(t==='N')pos=24-d*7;else if(t==='B')pos=12-d*3;else if(t==='Q')pos=5-d;else if(t==='K')pos=p.fullmoveNumber<20?d*2:14-d*4;
127:     score+=(c==='w'?1:-1)*(MATERIAL[t]+pos);
128:   }return score;
129: }
130: function moveOrderScore(p,m){const attacker=typeOf(p.board[m.from]),target=p.board[m.to];return(target?10*MATERIAL[typeOf(target)]-MATERIAL[attacker]:0)+(m.promotion?MATERIAL[m.promotion]+800:0);}
131: function orderedMoves(p,moves){return moves.sort((a,b)=>moveOrderScore(p,b)-moveOrderScore(p,a));}
132: function search(p,depth,alpha,beta,ply,state){
133:   state.nodes++;const key=repetitionKey(p);
134:   if((p.repetitionCounts?.[key]||0)+(state.pathCounts[key]||0)>=3||(p.halfmoveClock||0)>=100||isInsufficientMaterial(p))return 0;
135:   const moves=legalMoves(p),checked=isInCheck(p,p.turn);if(!moves.length)return checked?-100000+ply:0;
136:   if(depth<=0||state.nodes>=state.nodeLimit)return evaluateWhite(p)*(p.turn==='w'?1:-1)+(checked?-25:0);
137:   let best=-Infinity;for(const m of orderedMoves(p,moves)){
138:     const child=applyUnchecked(p,m,false),childKey=repetitionKey(child);state.pathCounts[childKey]=(state.pathCounts[childKey]||0)+1;
139:     const score=-search(child,depth-1,-beta,-alpha,ply+1,state);state.pathCounts[childKey]--;
140:     if(!state.pathCounts[childKey])delete state.pathCounts[childKey];if(score>best)best=score;if(score>alpha)alpha=score;if(alpha>=beta||state.nodes>=state.nodeLimit)break;
141:   }return best;
142: }
143: /** Choose a legal move; strength is 1–5 or {level, random}. Returns null if game over. */
144: export function getBotMove(p,strength=2,options={}){
145:   normalizePosition(p);const level=Math.max(1,Math.min(5,Math.round(typeof strength==='object'?(strength.level??2):strength)));
146:   const random=(typeof strength==='object'&&strength.random)||options.random||Math.random,moves=orderedMoves(p,legalMoves(p));
147:   if(!moves.length||getStatus(p).over)return null;
148:   if(level===1){const ranked=moves.map(m=>({move:m,score:evaluateWhite(applyUnchecked(p,m,false))*(p.turn==='w'?1:-1)+(moveOrderScore(p,m)>0?20:0)})).sort((a,b)=>b.score-a.score);
149:     const shortlist=ranked.slice(0,Math.max(1,Math.ceil(ranked.length*.55)));return shortlist[Math.floor(random()*shortlist.length)].move;}
150:   const depth=level===2?2:level===3?3:4,state={nodes:0,nodeLimit:level>=5?18000:level===4?12000:10000,pathCounts:{}};let bestScore=-Infinity,best=[],alpha=-Infinity,beta=Infinity;
151:   for(const m of moves){const child=applyUnchecked(p,m,false),key=repetitionKey(child);state.pathCounts[key]=(state.pathCounts[key]||0)+1;
152:     const score=-search(child,depth-1,-beta,-alpha,1,state);state.pathCounts[key]--;if(!state.pathCounts[key])delete state.pathCounts[key];
153:     if(score>bestScore){bestScore=score;best=[m];}else if(score===bestScore)best.push(m);if(score>alpha)alpha=score;if(state.nodes>=state.nodeLimit)break;}
154:   if(level<=3&&best.length>1)return best[Math.floor(random()*best.length)];return best[0]||moves[0]||null;
155: }
156: export const botMove=getBotMove;

