import { createInitialPosition, legalMoves, makeMove, getStatus, fromFEN } from './src/chess.js';
let p = createInitialPosition();
if (legalMoves(p).length !== 20) throw new Error('initial move count');
p = makeMove(p, {from:'e2',to:'e4'});
p = makeMove(p, {from:'e7',to:'e5'});
if (getStatus(p).over) throw new Error('unexpected game over');
const promotion = fromFEN('4k3/P7/8/8/8/8/8/4K3 w - - 0 1');
const promotions = legalMoves(promotion, 'a7').filter(m => m.to === 'a8').map(m => m.promotion);
if (promotions.join('') !== 'QRBN') throw new Error(`promotion choices: ${promotions}`);
const castling = fromFEN('r3k2r/8/8/8/8/8/8/R3K2R w KQkq - 0 1');
if (!legalMoves(castling, 'e1').some(m => m.to === 'g1') || !legalMoves(castling, 'e1').some(m => m.to === 'c1')) throw new Error('castling');
console.log(JSON.stringify({initialLegalMoves:20, promotionChoices:promotions, castling:'both sides available', status:getStatus(p).result}));
EOF

